import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";import"./chunks/assets.tD9y118P.js";var i=JSON.parse(`{"title":"Scenario / Create","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","frontmatter":{"title":"Scenario / Create","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}]],"sort":500},"headers":[],"relativePath":"en/synceta/scenario-create.md","filePath":"en/synceta/scenario-create.md","lastUpdated":1784421849000}`),a={name:`en/synceta/scenario-create.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to “Scenario”">​</a></h1><p>Using SyncETA, you can create and manage test cases through the actual UI without writing complex test code.</p><h2 id="what-is-a-scenario" tabindex="-1">What is a Scenario? <a class="header-anchor" href="#what-is-a-scenario" aria-label="Permalink to “What is a Scenario?”">​</a></h2><h4 id="a-scenario-refers-to-a-functional-test-unit-like-the-following" tabindex="-1">A <strong><em>&#39;Scenario&#39;</em></strong> refers to a functional test unit like the following. <a class="header-anchor" href="#a-scenario-refers-to-a-functional-test-unit-like-the-following" aria-label="Permalink to “A &#39;Scenario&#39; refers to a functional test unit like the following.”">​</a></h4><h5 id="access-the-empasy-homepage-and-send-an-inquiry" tabindex="-1">[ Access the <strong><em>&#39;empasy&#39;</em></strong> homepage and send an inquiry ] <a class="header-anchor" href="#access-the-empasy-homepage-and-send-an-inquiry" aria-label="Permalink to “[ Access the &#39;empasy&#39; homepage and send an inquiry ]”">​</a></h5><ol><li>Access the <strong><em>&#39;empasy&#39;</em></strong> homepage.</li><li>Click <strong><em>&#39;Contact Us&#39;</em></strong>.</li><li>Enter inquiry details.</li><li>Send inquiry.</li><li>Verify successful transmission.</li></ol><h2 id="create-scenario" tabindex="-1">Create Scenario <a class="header-anchor" href="#create-scenario" aria-label="Permalink to “Create Scenario”">​</a></h2><h4 id="_1-go-to-scenario-menu" tabindex="-1">1. Go to Scenario Menu <a class="header-anchor" href="#_1-go-to-scenario-menu" aria-label="Permalink to “1. Go to Scenario Menu”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>Click the <strong><em>&#39;Scenario&#39;</em></strong> menu on the left sidebar</li><li>Click <strong><em>&#39;New Scenario&#39;</em></strong> at the top right</li><li>A settings modal required for scenario recording will appear.</li></ol></div><p><img src="/docs/assets/new_scenario.CxnBoB7X.png" alt="Click Create Scenario" loading="lazy"></p><h4 id="_2-set-recording-browser" tabindex="-1">2. Set Recording Browser <a class="header-anchor" href="#_2-set-recording-browser" aria-label="Permalink to “2. Set Recording Browser”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>Enter the URL of the webpage to create the scenario.</li><li>Select the browser for recording.</li></ol><ul><li>Can choose Chrome for recording -&gt; Edge for execution (Cross-browsing test)</li></ul><ol start="3"><li>Set the size of the browser for recording.</li></ol><ul><li>1400 x 800 for recording -&gt; 800 x 600 for execution is possible (Responsive test)</li></ul></div><p><img src="/docs/assets/select_option.BO9WUS-y.png" alt="Pre-recording Settings" loading="lazy"></p><h4 id="_3-set-collection-events" tabindex="-1">3. Set Collection Events <a class="header-anchor" href="#_3-set-collection-events" aria-label="Permalink to “3. Set Collection Events”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>After selecting the event type to collect, click the start recording button at the bottom right of the modal.<br> It is recommended to proceed with recording using the default settings.</li></ul></div><p><img src="/docs/assets/allow_event.BTzP3-1K.png" alt="Allow Event Settings" loading="lazy"></p><h4 id="_4-start-recording" tabindex="-1">4. Start Recording <a class="header-anchor" href="#_4-start-recording" aria-label="Permalink to “4. Start Recording”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>When you start recording, the browser will appear on the screen.<br> Please proceed with the actual test in that browser.<br> EX) Search for <strong><em>&#39;nearby restaurants&#39;</em></strong> on Naver</p><p>You can see that records have been collected as shown in the picture.</p><ol><li>Move to URL</li><li>Click search bar</li><li>Enter search term (<strong><em>&#39;nearby restaurants&#39;</em></strong>)</li><li>Click search button</li></ol></div><p><img src="/docs/assets/start_recording.C0eDEaiH.png" alt="Start Recording" loading="lazy"></p><h4 id="_4-collect-dom-information" tabindex="-1">4. Collect DOM Information <a class="header-anchor" href="#_4-collect-dom-information" aria-label="Permalink to “4. Collect DOM Information”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>All records have information about the DOM where the event occurred.<br> EX) Collect attributes of the input element where the search term (<strong><em>&#39;nearby restaurants&#39;</em></strong>) was entered</li></ul></div><p><img src="/docs/assets/select_dom_info.Dv7Rqw5o.png" alt="Select DOM Info" loading="lazy"></p><h4 id="_5-when-a-new-tab-opens-during-recording" tabindex="-1">5. When a new tab opens during recording <a class="header-anchor" href="#_5-when-a-new-tab-opens-during-recording" aria-label="Permalink to “5. When a new tab opens during recording”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>You can continue scenario recording in the exact same way on any new tab added in the browser.</p></div><p><img src="/docs/assets/new_tap.JQeqWugH.png" alt="New Tab" loading="lazy"></p><h2 id="wait-record" tabindex="-1">Wait Record <a class="header-anchor" href="#wait-record" aria-label="Permalink to “Wait Record”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This is a function that gives a wait time between executions of records until a specific condition is met.</p><p>3 Types of Wait Records</p><ol><li>Time Wait - Waits for the set time.</li><li>Element Exposure Wait - Waits until a specific element appears on the screen.</li><li>Element Value Match Wait - Waits until a specific value is exposed on the screen.</li></ol></div><h4 id="_1-add-time-wait-condition" tabindex="-1">1. Add Time Wait Condition <a class="header-anchor" href="#_1-add-time-wait-condition" aria-label="Permalink to “1. Add Time Wait Condition”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Grants wait time before executing a record.</p><ol><li>Right-click the record that requires waiting.</li><li>Click Add Wait Condition and set the wait time. (1000 = 1 second)</li></ol></div><p>Right-click record <img src="/docs/assets/time_wait.Ck2J4xsR.png" alt="Time Wait" loading="lazy"> Set Wait Time <img src="/docs/assets/time_wait2.BN7q3QL7.png" alt="Set Time Wait" loading="lazy"> Create Wait Record <img src="/docs/assets/time_wait3.Di0WXHU3.png" alt="Create Wait Record" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Add a time wait condition to wait for screen loading (about 3 seconds considering network conditions) after moving to URL, then click the search bar</p></div><h4 id="_2-add-element-exposure-wait-condition" tabindex="-1">2. Add Element Exposure Wait Condition <a class="header-anchor" href="#_2-add-element-exposure-wait-condition" aria-label="Permalink to “2. Add Element Exposure Wait Condition”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Waits until a specific element is exposed on the screen.</p><ol><li>Right-click the record that requires waiting.</li><li>Click Add Wait Condition and select Element Exposure Wait.</li></ol></div><p>Right-click record <img src="/docs/assets/dom_wait.DhHz2jZ9.png" alt="DOM Wait" loading="lazy"> After clicking Select Element on the recording screen,<br> Select the element to wait for in the browser where recording is in progress. <img src="/docs/assets/dom_wait2.C30_95jZ.png" alt="Select DOM" loading="lazy"> Create Element Exposure Wait Record <img src="/docs/assets/dom_wait3.CBtQ6C0E.png" alt="Create DOM Wait" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Wait until the search bar (input) is actually loaded on the screen before clicking the search bar</p></div><h4 id="_3-add-element-value-match-wait-condition" tabindex="-1">3. Add Element Value Match Wait Condition <a class="header-anchor" href="#_3-add-element-value-match-wait-condition" aria-label="Permalink to “3. Add Element Value Match Wait Condition”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Waits until the set value is exposed on a specific element.</p></div><p>Right-click record <img src="/docs/assets/value_wait.97BmEy8x.png" alt="Value Wait" loading="lazy"> After clicking Select Element on the recording screen,<br> Select the element to wait for in the browser where recording is in progress. <img src="/docs/assets/value_wait2.W3u2wB2D.png" alt="Select Value" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Wait until <strong><em>&#39;Hankyung Business&#39;</em></strong> is exposed on the news carousel</p></div><h2 id="verification-record" tabindex="-1">Verification Record <a class="header-anchor" href="#verification-record" aria-label="Permalink to “Verification Record”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This is a function to verify whether a specific element or a specific value is exposed between executions of records.</p><ol><li>Verify whether a specific element is exposed on the screen<br> EX) Check if <strong><em>&#39;Restaurant Map&#39;</em></strong> is exposed on the screen after searching for restaurants</li><li>Verify whether a specific value is exposed on the screen<br> EX) Check if <strong><em>&#39;OO Restaurant&#39;</em></strong> is exposed at the top of <strong><em>&#39;Places&#39;</em></strong></li></ol></div><h4 id="_1-add-element-exposure-verification-record" tabindex="-1">1. Add Element Exposure Verification Record <a class="header-anchor" href="#_1-add-element-exposure-verification-record" aria-label="Permalink to “1. Add Element Exposure Verification Record”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Verifies whether a specific element is exposed on the screen.</p></div><p>Right-click record <img src="/docs/assets/valid_dom.2uHkx6Bq.png" alt="Valid DOM" loading="lazy"> After clicking Select Element on the recording screen,<br> Select the element to verify in the browser where recording is in progress. <img src="/docs/assets/valid_dom2.DSYmGpNO.png" alt="Select Valid DOM" loading="lazy"> Create Verification Record <img src="/docs/assets/valid_dom3.D3yXzcTH.png" alt="Create Valid DOM" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Verify whether <strong><em>&#39;Places&#39;</em></strong> is exposed after searching for <strong><em>&#39;nearby restaurants&#39;</em></strong> on Naver.</p></div><h4 id="_2-add-element-value-verification-record" tabindex="-1">2. Add Element Value Verification Record <a class="header-anchor" href="#_2-add-element-value-verification-record" aria-label="Permalink to “2. Add Element Value Verification Record”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Verifies whether a specific value is exposed on the screen.</p></div><p>Right-click record <img src="/docs/assets/valid_value.CTFJE1s6.png" alt="Valid Value" loading="lazy"> After clicking Select Element on the recording screen,<br> Select the element to verify in the browser where recording is in progress.<br> EX) Verify whether <strong><em>&#39;Dearest Yeonnam&#39;</em></strong> is exposed at the top of Places <img src="/docs/assets/valid_value2.BB6NnGlc.png" alt="Select Valid Value" loading="lazy"> Create Verification Record <img src="/docs/assets/valid_value3.PHN3oOuY.png" alt="Create Valid Value" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Check if <strong><em>&#39;Dearest Yeonnam&#39;</em></strong> is exposed at the top of <strong><em>&#39;Places&#39;</em></strong></p></div><h4 id="_3-screen-verification-using-ai" tabindex="-1">3. Screen Verification using AI <a class="header-anchor" href="#_3-screen-verification-using-ai" aria-label="Permalink to “3. Screen Verification using AI”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Used when image-based verification is needed, rather than the exposure of specific values or elements on the screen.</p></div><p>Right-click record <img src="/docs/assets/valid_ai.BLlZ6YWJ.png" alt="Valid AI" loading="lazy"> Select AI Prompt and enter the prompt.<br> The Sync-ETA agent automatically captures the current browser screen and verifies it with AI.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Using AWS Bedrock - claude-3-haiku model</p></div><p><img src="/docs/assets/valid_ai2.BNZ_hmqg.png" alt="Enter AI Prompt" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Check if <strong><em>&#39;Map&#39;</em></strong> is normally exposed on the screen after searching for <strong><em>&#39;nearby restaurants&#39;</em></strong></p></div><h2 id="edit-scenario" tabindex="-1">Edit Scenario <a class="header-anchor" href="#edit-scenario" aria-label="Permalink to “Edit Scenario”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This is a feature to continue recording from a specific part of an existing scenario.</p></div><h4 id="_1-select-scenario-to-edit" tabindex="-1">1. Select Scenario to Edit <a class="header-anchor" href="#_1-select-scenario-to-edit" aria-label="Permalink to “1. Select Scenario to Edit”">​</a></h4><p>Click Edit Scenario <img src="/docs/assets/edit.DharqlJd.png" alt="Edit Scenario" loading="lazy"> Select the record from which to continue recording. <img src="/docs/assets/edit2.Ck35xb_N.png" alt="Select Edit Record" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>The recording browser appears just like when creating a scenario.</li><li>The script runs up to the record where you wish to continue recording.</li><li>Once the set record is reached, it collects events occurring in the browser from that point onward.</li></ol></div><p><img src="/docs/assets/edit3.CiNnpFll.png" alt="Execute Edit Script" loading="lazy"></p><h2 id="additional-features" tabindex="-1">Additional Features <a class="header-anchor" href="#additional-features" aria-label="Permalink to “Additional Features”">​</a></h2><h4 id="_1-note-feature" tabindex="-1">1. Note Feature <a class="header-anchor" href="#_1-note-feature" aria-label="Permalink to “1. Note Feature”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Enter the contents of the record.</p></div><p><img src="/docs/assets/comment.bH8IGTY6.png" alt="Note Comment" loading="lazy"></p><h4 id="_2-failure-recovery-script" tabindex="-1">2. Failure Recovery Script <a class="header-anchor" href="#_2-failure-recovery-script" aria-label="Permalink to “2. Failure Recovery Script”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>If a record fails, a recovery script is executed.</p></div><p><img src="/docs/assets/recover.BpaZA4Gc.png" alt="Failure Recover" loading="lazy"></p><h4 id="_3-dataset" tabindex="-1">3. Dataset <a class="header-anchor" href="#_3-dataset" aria-label="Permalink to “3. Dataset”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Specifies the input value.<br> EX) Replaces the search term (<strong><em>&#39;nearby restaurants&#39;</em></strong>) with a value specified by the user.<br> ** For detailed explanation, refer to **<em>&#39;Dataset&#39;</em>**</p></div><p><img src="/docs/assets/dataset.BNYNMS0h.png" alt="Dataset" loading="lazy"></p><h4 id="_4-delete" tabindex="-1">4. Delete <a class="header-anchor" href="#_4-delete" aria-label="Permalink to “4. Delete”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Deletes the collected record.<br> EX) If you click the wrong part while recording, delete that record.</p></div><p><img src="/docs/assets/delete.BiOSPnzX.png" alt="Delete Record" loading="lazy"></p><h4 id="_5-disable" tabindex="-1">5. Disable <a class="header-anchor" href="#_5-disable" aria-label="Permalink to “5. Disable”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Excludes collected information during execution without deleting it.</p></div><p><img src="/docs/assets/disable.BWI2I4rp.png" alt="Disable Record" loading="lazy"></p>`,77)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};